import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { login, isAuthenticated, getUserRole } from '../utils/auth';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import './styles/Login.scss';
import CreateAccount from './CreateAccount';

function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [authorName, setAuthorName] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (isAuthenticated()) {
      const role = getUserRole();
      navigate(role === 'editor' ? '/editor' : '/admin');
    }
  }, [navigate]);

  const handleSubmit = (e) => {
    e.preventDefault();
  
    if (!authorName.trim()) {
      toast.error('Please enter your name');
      return;
    }
  
    // ✅ Check localStorage users first
    const users = JSON.parse(localStorage.getItem('cms-users') || '[]');
    const match = users.find(
      (u) =>
        u.email === email.trim() &&
        u.password === password &&
        u.name.toLowerCase() === authorName.trim().toLowerCase()
    );
  
    if (match) {
      login(match.role || 'editor', 30, match.name); // ✅ Log them in with stored role + name
      toast.success(`Welcome back, ${match.name}`);
      setTimeout(() => {
        navigate(match.role === 'admin' ? '/admin' : '/editor');
      }, 1000);
      return;
    }
  
    // Optional: fallback for hardcoded admin if desired
    if (email === 'admin@example.com' && password === 'admin123') {
      login('admin', 30, authorName.trim());
      toast.success('Welcome, Admin!');
      setTimeout(() => navigate('/admin'), 1000);
    } else {
      setError('Invalid credentials');
      toast.error('Login failed');
    }
  };

  return (
    <div className="login container">
      <ToastContainer />
      <form className="login__form" onSubmit={handleSubmit}>
        <h2 className="login__title">CMS Login</h2>

        {error && <div className="login__error">{error}</div>}

        <input
          type="text"
          placeholder="Your Name"
          value={authorName}
          onChange={(e) => setAuthorName(e.target.value)}
          required
        />

        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />

        <div className="login__password-wrapper">
          <input
            type={showPass ? 'text' : 'password'}
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button
            type="button"
            className="login__toggle"
            onClick={() => setShowPass(!showPass)}
          >
            {showPass ? 'Hide' : 'Show'}
          </button>
        </div>

        <button type="submit" className="login__submit">Login</button>
        <Link to="/register">
          Create Account
        </Link>
      </form>
    </div>
  );
}

export default Login;
